<script>function bsToggleQTypeMenu(b){b.nextElementSibling.classList.toggle('hidden')}function bsSelectQType(b,t){document.getElementById('bs_question_type_input').value=t;const d=b.closest('.bs-qtype-dropdown');d.querySelector('.bs-qtype-icon').textContent=t==='pilihan_ganda'?'◉':'☰';d.querySelector('.bs-qtype-menu').classList.add('hidden');document.getElementById('bank-qtype-essay').style.display=t==='essay'?'block':'none';document.getElementById('bank-qtype-mc').style.display=t==='pilihan_ganda'?'block':'none'}function bsWrap(b,a,c){const e=b.closest('.bs-field').querySelector('textarea'),s=e.selectionStart,n=e.selectionEnd,v=e.value;e.value=v.slice(0,s)+a+(v.slice(s,n)||'teks')+c+v.slice(n);e.focus()}document.addEventListener('click',e=>{if(!e.target.closest('.bs-qtype-dropdown'))document.querySelectorAll('.bs-qtype-menu').forEach(m=>m.classList.add('hidden'))});function bsImagePreview(input){const toolbar=input.closest('[data-bs-toolbar]');const box=toolbar?.querySelector('[data-bs-image]');const file=input.files?.[0];if(!box)return;if(!file){box.innerHTML='';box.classList.remove('has-file');return}const flag=document.querySelector('[data-remove-image]');if(flag)flag.value='0';const name=file.name.length>18?file.name.slice(0,15)+'...':file.name;box.innerHTML=`<span title="${file.name}">${name}</span><button type="button" onclick="bsRemoveImage(this)">&times;</button>`;box.classList.add('has-file')}function bsRemoveImage(button){const toolbar=button.closest('[data-bs-toolbar]');const box=toolbar?.querySelector('[data-bs-image]');const input=toolbar?.querySelector('input[type="file"][name="image"]');if(input)input.value='';const flag=document.querySelector('[data-remove-image]');if(flag)flag.value='1';if(box){box.innerHTML='';box.classList.remove('has-file')}}
</script><?php /**PATH D:\laragon\www\ctf_project\resources\views/managemenchallenge/questionbank/partials/form.blade.php ENDPATH**/ ?>